use super::*;
#[test]fn missing_business_table_and_corrupt_revision_never_look_like_empty_or_new_tasks(){
 let f=Fixture::new();let mut db=f.open();let value=report(&db,1,"running");db.report(&value).unwrap();db.store.db.execute("update tasks set payload='invalid'",[]).unwrap();assert!(db.store.revision("test-session",&std::env::var("COMPUTERNAME").unwrap_or_else(|_|"localhost".into())).is_err());db.store.db.execute("drop table tasks",[]).unwrap();drop(db);assert!(Database::open(f.profile.clone()).err().unwrap().contains("拒绝补建空表"));let db=Connection::open(f.root.join("events.sqlite3")).unwrap();assert_eq!(db.query_row::<i64,_,_>("select count(*) from sqlite_master where name='tasks'",[],|r|r.get(0)).unwrap(),0);
}
#[test]fn missing_runtime_evidence_stays_unknown_without_an_epoch_event(){
 let f=Fixture::new();let mut db=f.open();db.store.db.execute("insert into tasks values('missing',?1)",[json!({"id":"missing","status":"running","runtime":"unknown","updated_at":null,"revision":1,"plan":[],"blockers":[],"evidence":[]}).to_string()]).unwrap();db.runtime_gap(0.).unwrap();assert_eq!(db.store.db.query_row::<i64,_,_>("select count(*) from events",[],|r|r.get(0)).unwrap(),0);let task=&db.store.tasks().unwrap()[0];assert_eq!(task["updated_at"],Value::Null);assert_eq!(task["timing"]["started_at"],Value::Null);
}
#[test]fn read_only_notifications_and_idle_claim_do_not_advance_sequence(){
 let f=Fixture::new();let mut db=f.open();let n=Notifications::new(&f.root).unwrap();put(&db.store.db,"write_gate",&json!("open")).unwrap();let request=Request{protocol:2,profile_id:f.profile.profile_id.clone(),request_id:"read".into(),method:"notification_snapshot".into(),params:json!({})};let before=seq(&db.store.db).unwrap();db.call(&request,&n).unwrap();assert!(n.claim(&db.store.db).unwrap().is_none());assert_eq!(seq(&db.store.db).unwrap(),before);
}
#[test]fn watch_releases_on_commit_without_blocking_the_store_and_resyncs_identity(){
 let f=Fixture::new();let db=f.open();put(&db.store.db,"write_gate",&json!("open")).unwrap();drop(db);let actor=Actor::start(f.profile.clone()).unwrap();let request=Request{protocol:2,profile_id:f.profile.profile_id.clone(),request_id:"read".into(),method:"identity".into(),params:json!({})};let identity=actor.dispatcher()(request.clone()).unwrap();let dispatch=actor.dispatcher();let mut watch=request.clone();watch.method="watch".into();watch.params=identity.clone();let thread=std::thread::spawn(move||dispatch(watch).unwrap());let mut write=request.clone();write.method="preferences".into();write.params=json!({"theme":"light","settings_revision":0});actor.dispatcher()(write).unwrap();let changed=thread.join().unwrap();assert!(changed["commit_sequence"].as_u64()>identity["commit_sequence"].as_u64());let mut mismatch=request;mismatch.method="watch".into();mismatch.params=json!({"database_instance_id":"other","commit_sequence":changed["commit_sequence"]});assert_eq!(actor.dispatcher()(mismatch).unwrap()["database_instance_id"],identity["database_instance_id"]);
}
#[test]fn daily_backups_keep_fourteen_without_removing_manual_or_upgrade_backups(){
 let f=Fixture::new();let db=f.open();let manual=db.backup("manual",None).unwrap();let upgrade=db.backup("upgrade",None).unwrap();for _ in 0..16{advance(&db.store.db).unwrap();put(&db.store.db,"daily_backup",&json!({"day":-1,"sequence":0})).unwrap();db.daily_backup().unwrap();}let count=std::fs::read_dir(f.root.join("backups/daily")).unwrap().filter_map(|e|e.ok()).filter(|e|e.path().extension().is_some_and(|v|v=="sqlite3")).count();assert_eq!(count,14);assert!(std::path::Path::new(manual["path"].as_str().unwrap()).is_file());assert!(std::path::Path::new(upgrade["path"].as_str().unwrap()).is_file());
}
struct Fixture{root:PathBuf,profile:Profile}
#[test]fn paused_agent_does_not_dispatch_imported_pending_notifications(){
 use std::{net::TcpListener,time::{Duration,Instant}};
 let f=Fixture::new();let db=f.open();let n=Notifications::new(&f.root).unwrap();n.call(&db.store.db,"notification_save",&json!({"enabled":true})).unwrap();n.call(&db.store.db,"notification_channel_save",&json!({"id":"wecom","enabled":true,"webhook":"https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=synthetic-paused"})).unwrap();n.call(&db.store.db,"notification_test",&json!({"id":"wecom"})).unwrap();drop(n);drop(db);
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let url=format!("http://{}/test",listener.local_addr().unwrap()).parse().unwrap();let actor=Actor::start_with(f.profile.clone(),Ok(Arc::new(Notifications::for_test(&f.root,url).unwrap()))).unwrap();let until=Instant::now()+Duration::from_millis(1300);while Instant::now()<until{assert_eq!(listener.accept().err().unwrap().kind(),std::io::ErrorKind::WouldBlock);std::thread::sleep(Duration::from_millis(25));}drop(actor);
 let db=f.open();assert_eq!(get(&db.store.db,"notifications").unwrap().unwrap()["records"][0]["attempts"],0);
}
impl Fixture{
    fn new()->Self{let root=std::env::temp_dir().join(format!("floatboard-agent-test-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&root).unwrap();let profile=Profile{profile_id:uuid::Uuid::new_v4().to_string(),environment:"development".into(),owner_sid:floatboard_client::windows::sid().unwrap(),root:root.clone(),port:60001,agent_exe:root.join("FloatboardAgent.exe"),gui_exe:root.join("CodexFloatboard.exe"),codex_home:root.join("codex")};Self{root,profile}}
    fn open(&self)->Database{if self.root.join("events.sqlite3").exists(){Database::open(self.profile.clone()).unwrap()}else{Database::initialize(self.profile.clone()).unwrap()}}
}
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
fn report(db:&Database,revision:u64,status:&str)->Value{let record=db.session("test-session","D:/synthetic").unwrap();json!({"session_id":"test-session","session_token":record["session_token"],"revision":revision,"title":"Synthetic task","status":status,"plan":[{"id":"p","title":"Work","status":if status=="completed"{"completed"}else{"inProgress"}}],"blockers":[],"evidence":[{"label":"synthetic evidence"}]})}
#[test]fn committed_receipts_are_idempotent_across_restart(){let f=Fixture::new();let mut db=f.open();let value=report(&db,1,"running");let first=db.report(&value).unwrap();assert_eq!(first["accepted"],true);assert_eq!(db.report(&value).unwrap(),first);drop(db);let mut db=f.open();assert_eq!(db.report(&value).unwrap(),first);assert_eq!(db.store.tasks().unwrap().len(),1);}
#[test]fn conflicting_and_stale_revisions_are_rejected(){let f=Fixture::new();let mut db=f.open();let mut value=report(&db,1,"running");db.report(&value).unwrap();value["title"]=json!("Different");assert!(db.report(&value).unwrap_err().contains("冲突"));value["revision"]=json!(0);assert!(db.report(&value).unwrap_err().contains("current_revision=1"));}
#[test]fn failed_receipt_rolls_back_task_event_and_notifications(){let f=Fixture::new();let mut db=f.open();db.store.db.execute_batch("create trigger reject_receipt before insert on report_receipts begin select raise(abort,'synthetic'); end;").unwrap();let value=report(&db,1,"completed");assert!(db.report(&value).is_err());assert!(db.store.tasks().unwrap().is_empty());assert_eq!(seq(&db.store.db).unwrap(),0);assert_eq!(get(&db.store.db,"notifications").unwrap(),None);}
#[test]fn notification_outbox_commits_with_business_transition(){let f=Fixture::new();let mut db=f.open();let mut state=json!({"enabled":true,"baseline_reset":false,"subscriptions":{"task_completed":true},"channels":[{"id":"wecom","enabled":true,"webhook":"synthetic-ciphertext"}]});put(&db.store.db,"notifications",&state).unwrap();db.report(&report(&db,1,"completed")).unwrap();state=get(&db.store.db,"notifications").unwrap().unwrap();assert_eq!(state["records"].as_array().unwrap().len(),1);let receipt=db.report(&report(&db,1,"completed")).unwrap();assert_eq!(receipt["accepted"],true);assert_eq!(get(&db.store.db,"notifications").unwrap().unwrap()["records"].as_array().unwrap().len(),1);}
#[test]fn settings_request_can_be_recovered_without_duplicate_application(){let f=Fixture::new();let mut db=f.open();let request=Request{protocol:2,profile_id:f.profile.profile_id.clone(),request_id:"stable-id".into(),method:"preferences".into(),params:json!({"theme":"light","settings_revision":0})};let first=db.settings(&request).unwrap();assert_eq!(first["settings_revision"],1);assert_eq!(db.settings(&request).unwrap(),first);let mut changed=request.clone();changed.request_id="next".into();assert!(db.settings(&changed).is_err());changed.request_id="stable-id".into();changed.params["theme"]=json!("dark");assert!(db.settings(&changed).is_err());}
#[test]fn consistent_backup_contains_committed_data(){let f=Fixture::new();let mut db=f.open();db.report(&report(&db,1,"completed")).unwrap();let receipt=db.backup("manual",None).unwrap();let path=PathBuf::from(receipt["path"].as_str().unwrap());let backup=Connection::open_with_flags(path,rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();let count:i64=backup.query_row("select count(*) from tasks",[],|r|r.get(0)).unwrap();assert_eq!(count,1);assert_eq!(receipt["integrity"],"ok");}
#[test]fn missing_existing_database_never_becomes_new_empty_store(){let f=Fixture::new();let db=f.open();drop(db);std::fs::rename(f.root.join("events.sqlite3"),f.root.join("retained.sqlite3")).unwrap();assert!(Database::open(f.profile.clone()).err().unwrap().contains("拒绝创建空库"));assert!(!f.root.join("events.sqlite3").exists());}
#[test]fn corrupt_existing_database_is_preserved(){let f=Fixture::new();let path=f.root.join("events.sqlite3");std::fs::write(&path,b"synthetic corrupt database").unwrap();assert!(Database::open(f.profile.clone()).is_err());assert_eq!(std::fs::read(path).unwrap(),b"synthetic corrupt database");}
#[test]fn unexpected_database_identity_is_rejected(){let f=Fixture::new();let db=f.open();drop(db);atomic_json(&f.root.join("database-id.json"),&json!({"database_instance_id":"other"})).unwrap();assert!(Database::open(f.profile.clone()).err().unwrap().contains("不匹配"));}
#[test]fn newer_schema_is_rejected_without_downgrade(){let f=Fixture::new();let db=f.open();db.store.db.execute_batch("pragma user_version=999;").unwrap();drop(db);assert!(Database::open(f.profile.clone()).err().unwrap().contains("禁止降级"));}
#[test]fn domain_completion_does_not_follow_hook_stop(){let f=Fixture::new();let mut db=f.open();db.report(&report(&db,1,"running")).unwrap();db.hook(&json!({"hook_event_name":"Stop","session_id":"test-session","cwd":"D:/synthetic"})).unwrap();assert_eq!(db.store.tasks().unwrap()[0]["status"],"running");}
#[test]fn unauthenticated_report_does_not_write(){let f=Fixture::new();let mut db=f.open();let mut value=report(&db,1,"running");value["session_token"]=json!("wrong");assert!(db.report(&value).is_err());assert_eq!(seq(&db.store.db).unwrap(),0);}

#[test]fn interrupted_runtime_freezes_at_last_evidence_and_remains_partial(){let f=Fixture::new();let mut db=f.open();db.report(&report(&db,1,"running")).unwrap();let before=db.store.tasks().unwrap()[0]["timing"]["since"].as_f64().unwrap();db.runtime_gap(before+2.).unwrap();let t=&db.store.tasks().unwrap()[0];assert_eq!(t["status"],"running");assert_eq!(t["runtime"],"unknown");assert_eq!(t["timing"]["seconds"],2.);assert_eq!(t["timing"]["since"],Value::Null);assert_eq!(t["timing"]["partial"],true);}
#[test]fn full_database_rejects_report_without_a_success_receipt(){let f=Fixture::new();let mut db=f.open();let value=report(&db,1,"running");let pages:u32=db.store.db.query_row("pragma page_count",[],|r|r.get(0)).unwrap();db.store.db.execute_batch(&format!("pragma max_page_count={pages};")).unwrap();loop{if db.store.db.execute("insert into runtime_kv values(?1,?2)",params![uuid::Uuid::new_v4().to_string(),"x".repeat(3000)]).is_err(){break;}}
 let mut large=value.clone();large["plan"]=json!((0..100).map(|i|json!({"id":format!("step-{i}"),"title":"work ".repeat(50),"status":"pending"})).collect::<Vec<_>>());assert!(db.report(&large).is_err());assert_eq!(db.store.db.query_row::<i64,_,_>("select count(*) from report_receipts",[],|r|r.get(0)).unwrap(),0);}
#[test]fn orphan_wal_and_shared_main_links_are_rejected_without_new_database(){let f=Fixture::new();std::fs::write(f.root.join("events.sqlite3-wal"),b"orphan").unwrap();assert!(Database::initialize(f.profile.clone()).is_err());assert!(!f.root.join("events.sqlite3").exists());std::fs::remove_file(f.root.join("events.sqlite3-wal")).unwrap();let db=f.open();drop(db);let alias=f.root.join("alias.sqlite3");std::fs::hard_link(f.root.join("events.sqlite3"),&alias).unwrap();assert!(Database::open(f.profile.clone()).err().unwrap().contains("硬链接"));std::fs::remove_file(alias).unwrap();}
#[test]fn denied_database_access_is_an_error_and_preserves_original_bytes(){use std::os::windows::process::CommandExt;let f=Fixture::new();drop(f.open());let path=f.root.join("events.sqlite3");let before=std::fs::read(&path).unwrap();let sid=floatboard_client::windows::sid().unwrap();let status=std::process::Command::new("icacls.exe").arg(&path).arg("/deny").arg(format!("*{sid}:(W)")).creation_flags(0x08000000).output().unwrap();assert!(status.status.success());let outcome=Database::open(f.profile.clone());let restored=std::process::Command::new("icacls.exe").arg(&path).arg("/remove:d").arg(format!("*{sid}")).creation_flags(0x08000000).output().unwrap();assert!(restored.status.success());assert!(outcome.is_err());assert_eq!(std::fs::read(path).unwrap(),before);}
#[test]fn agent_delivers_without_gui_and_never_retries_an_unknown_result_after_restart(){
 use std::{net::TcpListener,io::{Read,Write},time::{Duration,Instant}};
 let f=Fixture::new();let mut db=f.open();put(&db.store.db,"write_gate",&json!("open")).unwrap();let n=Notifications::new(&f.root).unwrap();
 n.call(&db.store.db,"notification_save",&json!({"enabled":true})).unwrap();n.call(&db.store.db,"notification_channel_save",&json!({"id":"wecom","enabled":true,"webhook":"https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=synthetic-test"})).unwrap();db.report(&report(&db,1,"completed")).unwrap();drop(db);drop(n);
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();let url=format!("http://{}/test",listener.local_addr().unwrap()).parse::<url::Url>().unwrap();let server=std::thread::spawn(move||{let(mut socket,_)=listener.accept().unwrap();let mut bytes=[0;4096];assert!(socket.read(&mut bytes).unwrap()>0);socket.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 99\r\nConnection: close\r\n\r\n{").unwrap();});
 let actor=Actor::start_with(f.profile.clone(),Ok(Arc::new(Notifications::for_test(&f.root,url.clone()).unwrap()))).unwrap();let dispatch=actor.dispatcher();let request=Request{protocol:2,profile_id:f.profile.profile_id.clone(),request_id:"read".into(),method:"notification_snapshot".into(),params:json!({})};let until=Instant::now()+Duration::from_secs(8);loop{let state=dispatch(request.clone()).unwrap();if state["records"][0]["status"]=="unknown"{assert_eq!(state["records"][0]["attempts"],1);break;}assert!(Instant::now()<until);std::thread::sleep(Duration::from_millis(20));}server.join().unwrap();drop(dispatch);drop(actor);
 let actor=Actor::start_with(f.profile.clone(),Ok(Arc::new(Notifications::for_test(&f.root,url).unwrap()))).unwrap();let dispatch=actor.dispatcher();let state=dispatch(request).unwrap();assert_eq!(state["records"].as_array().unwrap().len(),1);assert_eq!(state["records"][0]["status"],"unknown");assert_eq!(state["records"][0]["attempts"],1);drop(dispatch);drop(actor);
}
